head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil25103";

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — votedisclsSubmitprn

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_conds();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil25103.onpageload' });
    }
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "btn_Modify", fn: function(){ return (!(String(((dma_pageContext.get("votedisclsSubmitprn") ?? "")) == null ? '' : ((dma_pageContext.get("votedisclsSubmitprn") ?? ""))).length === 0)); } }, { id: "c_otherwise_130", fn: function(){ return (!((!(String(((dma_pageContext.get("votedisclsSubmitprn") ?? "")) == null ? '' : ((dma_pageContext.get("votedisclsSubmitprn") ?? ""))).length === 0)))); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        scwin.initValue();

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil25103.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name slc_selEmail_onchange
 * @description slc_selEmail 변경 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.slc_selEmail_onchange = function(e){
    try {
        ((s, t) => { if (t && t.setValue) { t.setValue((s && s.getValue) ? s.getValue() : ""); } const i = (s && typeof s.getSelectedIndex === "function") ? s.getSelectedIndex() : -1; if (i === 0 && t && t.focus) { t.focus(); } })($c.util.getComponent("slc_selEmail"), $c.util.getComponent('ipt_email2'));

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil25103.slc_selEmail_onchange' }); }
};

/**
 * @method
 * @name btn_Modify_onclick
 * @description 「수정」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Modify_onclick = async function(e){
    try {
        await scwin.modify('update')

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil25103.btn_Modify_onclick' }); }
};

/**
 * @method
 * @name btn_Modify_2_onclick
 * @description 「저장」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Modify_2_onclick = async function(e){
    try {
        await scwin.modify('insert')

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil25103.btn_Modify_2_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_Modify
 * @description Modify 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Modify = async function () {
    const sbmOptions = {
        id: "tx_fn_Modify",
        method: "post",
        action: "/account/voteDiscls.do",
        ref: "dma_ModifyReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name modify
 * @description modify 처리
 * @param {String} _doFlag _doFlag
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.modify = async function (_doFlag) {
    const frm = (document.votedisclsForm || { elements: [] });
    if (await scwin.checkRequired($c.util.getComponent('ipt_corpRegNo'))) {
        return;
    }
    if ($c.util.getComponent('ipt_corpRegNo').getValue().length !== 13) {
        await $c.win.alert(((__a) => ((__a && __a.getAttribute) ? ((__a.getAttribute("alt") || __a.getAttribute("toolTip") || (__a.getTitle ? (__a.getTitle() ?? "") : "")) || "") : (__a ? (__a.alt ?? "") : "")))($c.util.getComponent('ipt_corpRegNo')) + '는 13자리입니다.');
        $c.util.getComponent("ipt_corpRegNo").focus();
        return;
    }
    if (!(scwin.isNumberInput($c.util.getComponent('ipt_corpRegNo')))) {
        await $c.win.alert('법인등록번호는 숫자만 입력하세요');
        return;
    }
    if (await scwin.checkRequired($c.util.getComponent('ipt_bzRegNo'))) {
        return;
    }
    if ($c.util.getComponent('ipt_bzRegNo').getValue().length !== 10) {
        await $c.win.alert(((__a) => ((__a && __a.getAttribute) ? ((__a.getAttribute("alt") || __a.getAttribute("toolTip") || (__a.getTitle ? (__a.getTitle() ?? "") : "")) || "") : (__a ? (__a.alt ?? "") : "")))($c.util.getComponent('ipt_bzRegNo')) + '는 10자리입니다.');
        $c.util.getComponent("ipt_bzRegNo").focus();
        return;
    }
    if (!(scwin.isNumberInput($c.util.getComponent('ipt_bzRegNo')))) {
        await $c.win.alert('사업자등록번호는 숫자만 입력하세요');
        return;
    }
    if (await scwin.checkRequired($c.util.getComponent('ipt_corpNm'))) {
        return;
    }
    if (await (async (c) => { const v = String((c && c.getValue) ? (c.getValue() ?? "") : ""); const max = Number((c && c.getUserData) ? ((c.getUserData("maxByteLength") || c.getUserData("maxLength")) ?? 0) : 0) || 0; if (max && $c.str.getByteLength(v) > max) { const lbl = ""; await $c.win.alert((lbl ? ("'" + lbl + "' 항목은 ") : "") + "한글 " + (max / 2) + "자, 영문 " + max + "자까지 가능합니다."); return true; } return false; })($c.util.getComponent('ipt_corpNm'))) {
        return;
    }
    if (await scwin.checkRequired($c.util.getComponent('ipt_corpAbbrv'))) {
        return;
    }
    if (await (async (c) => { const v = String((c && c.getValue) ? (c.getValue() ?? "") : ""); const max = Number((c && c.getUserData) ? ((c.getUserData("maxByteLength") || c.getUserData("maxLength")) ?? 0) : 0) || 0; if (max && $c.str.getByteLength(v) > max) { const lbl = ""; await $c.win.alert((lbl ? ("'" + lbl + "' 항목은 ") : "") + "한글 " + (max / 2) + "자, 영문 " + max + "자까지 가능합니다."); return true; } return false; })($c.util.getComponent('ipt_corpAbbrv'))) {
        return;
    }
    if (await scwin.checkRequired($c.util.getComponent('ipt_corpEngNm'))) {
        return;
    }
    if (await (async (c) => { const v = String((c && c.getValue) ? (c.getValue() ?? "") : ""); const max = Number((c && c.getUserData) ? ((c.getUserData("maxByteLength") || c.getUserData("maxLength")) ?? 0) : 0) || 0; if (max && $c.str.getByteLength(v) > max) { const lbl = ""; await $c.win.alert((lbl ? ("'" + lbl + "' 항목은 ") : "") + "한글 " + (max / 2) + "자, 영문 " + max + "자까지 가능합니다."); return true; } return false; })($c.util.getComponent('ipt_corpEngNm'))) {
        return;
    }
    if (await scwin.checkRequired($c.util.getComponent('ipt_corpEngAbbrv'))) {
        return;
    }
    if (await (async (c) => { const v = String((c && c.getValue) ? (c.getValue() ?? "") : ""); const max = Number((c && c.getUserData) ? ((c.getUserData("maxByteLength") || c.getUserData("maxLength")) ?? 0) : 0) || 0; if (max && $c.str.getByteLength(v) > max) { const lbl = ""; await $c.win.alert((lbl ? ("'" + lbl + "' 항목은 ") : "") + "한글 " + (max / 2) + "자, 영문 " + max + "자까지 가능합니다."); return true; } return false; })($c.util.getComponent('ipt_corpEngAbbrv'))) {
        return;
    }
    if (await scwin.checkRequired($c.util.getComponent('ipt_chrgNm'))) {
        return;
    }
    if (await (async (c) => { const v = String((c && c.getValue) ? (c.getValue() ?? "") : ""); const max = Number((c && c.getUserData) ? ((c.getUserData("maxByteLength") || c.getUserData("maxLength")) ?? 0) : 0) || 0; if (max && $c.str.getByteLength(v) > max) { const lbl = ""; await $c.win.alert((lbl ? ("'" + lbl + "' 항목은 ") : "") + "한글 " + (max / 2) + "자, 영문 " + max + "자까지 가능합니다."); return true; } return false; })($c.util.getComponent('ipt_chrgNm'))) {
        return;
    }
    if (await scwin.checkRequired($c.util.getComponent('ipt_jobtitlNm'))) {
        return;
    }
    if (await (async (c) => { const v = String((c && c.getValue) ? (c.getValue() ?? "") : ""); const max = Number((c && c.getUserData) ? ((c.getUserData("maxByteLength") || c.getUserData("maxLength")) ?? 0) : 0) || 0; if (max && $c.str.getByteLength(v) > max) { const lbl = ""; await $c.win.alert((lbl ? ("'" + lbl + "' 항목은 ") : "") + "한글 " + (max / 2) + "자, 영문 " + max + "자까지 가능합니다."); return true; } return false; })($c.util.getComponent('ipt_jobtitlNm'))) {
        return;
    }
    if (await scwin.checkRequired($c.util.getComponent('ipt_depNm'))) {
        return;
    }
    if (await (async (c) => { const v = String((c && c.getValue) ? (c.getValue() ?? "") : ""); const max = Number((c && c.getUserData) ? ((c.getUserData("maxByteLength") || c.getUserData("maxLength")) ?? 0) : 0) || 0; if (max && $c.str.getByteLength(v) > max) { const lbl = ""; await $c.win.alert((lbl ? ("'" + lbl + "' 항목은 ") : "") + "한글 " + (max / 2) + "자, 영문 " + max + "자까지 가능합니다."); return true; } return false; })($c.util.getComponent('ipt_depNm'))) {
        return;
    }
    if (await scwin.checkRequired($c.util.getComponent('ipt_telNo1')) || await scwin.checkRequired($c.util.getComponent('ipt_telNo2')) || await scwin.checkRequired($c.util.getComponent('ipt_telNo3'))) {
        return;
    }
    if (!(scwin.isNumberInput($c.util.getComponent('ipt_telNo1')) && scwin.isNumberInput($c.util.getComponent('ipt_telNo2')) && scwin.isNumberInput($c.util.getComponent('ipt_telNo3')))) {
        await $c.win.alert('유선전화번호는 숫자만 입력하세요');
        return;
    }
    if (!(scwin.isNumberInput($c.util.getComponent('ipt_submitprnInnrNo')))) {
        await $c.win.alert('내선은 숫자만 입력하세요');
        return;
    }
    if (await scwin.checkRequired($c.util.getComponent('slc_cellphoneNo1')) || await scwin.checkRequired($c.util.getComponent('ipt_cellphoneNo2')) || await scwin.checkRequired($c.util.getComponent('ipt_cellphoneNo3'))) {
        return;
    }
    if (!(scwin.isNumberInput($c.util.getComponent('slc_cellphoneNo1')) && scwin.isNumberInput($c.util.getComponent('ipt_cellphoneNo2')) && scwin.isNumberInput($c.util.getComponent('ipt_cellphoneNo3')))) {
        await $c.win.alert('휴대전화번호는 숫자만 입력하세요');
        return;
    }
    if (await scwin.checkRequired($c.util.getComponent('ipt_faxNo1')) || await scwin.checkRequired($c.util.getComponent('ipt_faxNo2')) || await scwin.checkRequired($c.util.getComponent('ipt_faxNo3'))) {
        return;
    }
    if (!(scwin.isNumberInput($c.util.getComponent('ipt_faxNo1')) && scwin.isNumberInput($c.util.getComponent('ipt_faxNo2')) && scwin.isNumberInput($c.util.getComponent('ipt_faxNo3')))) {
        await $c.win.alert('FAX는 숫자만 입력하세요');
        return;
    }
    if (await scwin.checkRequired($c.util.getComponent('ipt_email1')) || await scwin.checkRequired($c.util.getComponent('ipt_email2'))) {
        return;
    }
    if (await scwin.checkRequired($c.util.getComponent('ipt_birthYear')) || await scwin.checkRequired($c.util.getComponent('ipt_birthMonth')) || await scwin.checkRequired($c.util.getComponent('ipt_birthDay'))) {
        return;
    }
    if (!await scwin.checkDateParts($c.util.getComponent('ipt_birthYear'), $c.util.getComponent('ipt_birthMonth'), $c.util.getComponent('ipt_birthDay'), false)) {
        return;
    }
    $c.util.getComponent('dma_ModifyReq').set('telNo', $c.util.getComponent('ipt_telNo1').getValue()+ '-' + $c.util.getComponent('ipt_telNo2').getValue()+ '-' + $c.util.getComponent('ipt_telNo3').getValue());
    $c.util.getComponent('dma_ModifyReq').set('cellphoneNo', $c.util.getComponent('slc_cellphoneNo1').getValue()+ '-' + $c.util.getComponent('ipt_cellphoneNo2').getValue()+ '-' + $c.util.getComponent('ipt_cellphoneNo3').getValue());
    $c.util.getComponent('dma_ModifyReq').set('faxNo', $c.util.getComponent('ipt_faxNo1').getValue()+ '-' + $c.util.getComponent('ipt_faxNo2').getValue()+ '-' + $c.util.getComponent('ipt_faxNo3').getValue());
    $c.util.getComponent('dma_ModifyReq').set('email', $c.str.trim($c.util.getComponent('ipt_email1').getValue()) + '@' + $c.str.trim($c.util.getComponent('ipt_email2').getValue()));
    $c.util.getComponent('dma_ModifyReq').set('birthdd', $c.util.getComponent('ipt_birthYear').getValue()+ $c.util.getComponent('ipt_birthMonth').getValue()+ $c.util.getComponent('ipt_birthDay').getValue());
    if (!$c.str.isEmail($c.util.getComponent('dma_ModifyReq').get('email'))) {
        return;
    }
    $c.util.getComponent('dma_ModifyReq').set('doFlag', _doFlag);
    $c.util.getComponent('dma_ModifyReq').set('method', 'modifyVotedisclsSubmitprn');
    frm.action = 'voteDiscls.do';
    await scwin.tx_fn_Modify();
};

/**
 * @method
 * @name initValue
 * @description init Value 처리
 * @returns {void}
 * @hidden N
 */
scwin.initValue = function () {
    const frm = (document.votedisclsForm || { elements: [] });
    const telNoVal = $c.util.getComponent('dma_ModifyReq').get('telNo');
    const cellphoneNoVal = $c.util.getComponent('dma_ModifyReq').get('cellphoneNo');
    const faxNoVal = $c.util.getComponent('dma_ModifyReq').get('faxNo');
    const emailVal = $c.util.getComponent('dma_ModifyReq').get('email');
    ((v) => { let cur = String(v ?? ""); for (let i = 3; i >= 1; i--) { const idx = cur.lastIndexOf("-"); const part = cur.substring(idx + 1); const c = $c.util.getComponent("telNo" + i); if (c && c.setValue) { c.setValue(part); } cur = cur.substring(0, idx); } })(telNoVal);
    ((v) => { let cur = String(v ?? ""); for (let i = 3; i >= 1; i--) { const idx = cur.lastIndexOf("-"); const part = cur.substring(idx + 1); const c = $c.util.getComponent("cellphoneNo" + i); if (c && c.setValue) { c.setValue(part); } cur = cur.substring(0, idx); } })(cellphoneNoVal);
    ((v) => { let cur = String(v ?? ""); for (let i = 3; i >= 1; i--) { const idx = cur.lastIndexOf("-"); const part = cur.substring(idx + 1); const c = $c.util.getComponent("faxNo" + i); if (c && c.setValue) { c.setValue(part); } cur = cur.substring(0, idx); } })(faxNoVal);
    ((v) => { let cur = String(v ?? ""); for (let i = 2; i >= 1; i--) { const idx = cur.lastIndexOf("@"); const part = cur.substring(idx + 1); const c = $c.util.getComponent("email" + i); if (c && c.setValue) { c.setValue(part); } cur = cur.substring(0, idx); } })(emailVal);
    const birthddVal = $c.util.getComponent('dma_ModifyReq').get('birthdd');
    $c.util.getComponent("ipt_birthYear").setValue(birthddVal.substring(0, 4));
    $c.util.getComponent("ipt_birthMonth").setValue(birthddVal.substring(4, 6));
    $c.util.getComponent("ipt_birthDay").setValue(birthddVal.substring(6));
};

/**
 * @method
 * @name checkDateParts
 * @description 년·월·일 입력칸 3개로 나뉜 날짜 검사(as-is 공통 fn_CheckDateGn — 공백 제거·숫자·월/일 범위, 실패 시 알림+포커스)
 * @param {*} yyyy 년 입력 컴포넌트
 * @param {*} mm 월 입력 컴포넌트
 * @param {*} dd 일 입력 컴포넌트
 * @param {String} flag true 면 빈 값도 검사
 * @returns {Promise<Boolean>} 유효하면 true(빈 값·flag 없음이면 undefined — as-is 동일)
 * @hidden N
 */
scwin.checkDateParts = async function (yyyy, mm, dd, flag) {
    [yyyy, mm, dd].forEach(function (c) { c.setValue($c.str.trim(String(c.getValue() ?? ""))); });
    const ymd = yyyy.getValue() + mm.getValue() + dd.getValue();
    if (yyyy.getValue() === "" || yyyy.getValue().length < 4) { await $c.win.alert("년을 제대로 입력해주세요."); yyyy.focus(); return false; }
    if (ymd === "" && !flag) { return; }
    for (const c of [yyyy, mm, dd]) {
        if (!/^\d*$/.test(String(c.getValue()).replace(/\s/g, ""))) { await $c.win.alert("숫자만 입력하셔야 합니다."); c.focus(); return false; }
    }
    const year = Number(yyyy.getValue()), month = Number(mm.getValue()), day = Number(dd.getValue());
    if (month < 1 || month > 12) { await $c.win.alert("존재하지 않는 월입니다."); mm.focus(); return false; }
    if (year <= 0) { await $c.win.alert("존재하지 않는 년도입니다."); dd.focus(); return false; }
    if (day > new Date(year, month, 0).getDate()) { await $c.win.alert("존재하지 않는 날짜입니다."); dd.focus(); return false; }
    return true;
};

/**
 * @method
 * @name checkRequired
 * @description 필수 입력 검사 — 값이 비면 항목명으로 알리고 포커스를 준 뒤 true(as-is fn_NullChk/fn_IsNull 의미 보존 · pcc/fil 반입 후보)
 * @param {Object} comp 입력 컴포넌트
 * @param {*} fieldName 항목명(생략 시 컴포넌트 title → id)
 * @returns {Promise<Boolean>} 비어 있으면 true
 * @hidden N
 */
scwin.checkRequired = async function (comp, fieldName) {
    if (!comp || !$c.util.isEmpty($c.str.trim(String(comp.getValue() ?? "")))) { return false; }
    const name = fieldName || (typeof comp.getTitle === "function" && comp.getTitle()) || comp.getID();
    await $c.win.alert("'" + name + "' 항목을 입력하세요");
    comp.focus();
    return true;
};

/**
 * @method
 * @name isNumberInput
 * @description 숫자만 입력됐는지 검사 — 아니면 포커스를 주고 false(as-is fn_IsNumber 의미 보존 · pcc/fil 반입 후보)
 * @param {Object} comp 입력 컴포넌트
 * @returns {Boolean} 숫자(공백 제외)만이면 true
 * @hidden N
 */
scwin.isNumberInput = function (comp) {
    const v = String(comp.getValue() ?? "").replace(/\s/g, "");
    if (!/^\d*$/.test(v)) { comp.focus(); return false; }
    return true;
};
